mapper.select:
	/* signMapper.checkEmailExistence */
    SELECT EXISTS (
    	SELECT 
    		1
        FROM 
        	USER
        WHERE 
        	EMAIL = #{email}
	) AS FLAG_EXISTENCE

mapper.insert:
/* signMapper.insertUser */
INSERT INTO USER (
	USER_UID
	, EMAIL
	, `PASSWORD`
	, NAME
	, REGISTRATION_DATE
	, REGISTRATION_USER
) VALUES (
	#{userUid}
	, #{email}
	, #{password}
	, #{name}
	, NOW()
	, #{userUid}
)

mapper.update:
/* signMapper.upsertAutologinToken */
INSERT INTO AUTOLOGIN (
	USER_UID
  	, TOKEN_HASH
  	, EXPIRES_AT_EPOCH
  	, UA
  	, IP
  	, REGISTRATION_DATE
  	, UPDATED_DATE
)
VALUES (
    #{userUid}
	, #{tokenHash}
	, #{expiresAtEpoch}
	, #{ua}
	, #{ip}
	, NOW()
	, NOW()
)
ON DUPLICATE KEY UPDATE
	TOKEN_HASH        	= VALUES(TOKEN_HASH)
	, EXPIRES_AT_EPOCH  = VALUES(EXPIRES_AT_EPOCH)
	, UA                = VALUES(UA)
	, IP                = VALUES(IP)
	, UPDATED_DATE      = NOW()

mapper.delete:
/* signMapper.deleteAutologinTokenByUserUid */
DELETE FROM AUTOLOGIN
WHERE 
	USER_UID = #{userUid}
